/// The name and operands of an encoded opcode (the table id in its upper 16 bits, the index in the lower), where
/// dxc's tables have it.
pub(crate) fn operation(opcode: u32) -> Option<(&'static str, &'static str)> {
    let index = usize::try_from(opcode & 0xFFFF).ok()?;
    match opcode >> 16 {
        0x0 => CORE_OPS.get(index).copied(),
        0x8000 => EXPERIMENTAL_OPS.get(index).copied(),
        _ => None,
    }
}
